using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations ---

var notes = new List<string>();

[Description("Search the web for a query and return a list of result snippets. Use this to find information about a topic.")]
string WebSearch([Description("The search query")] string query)
{
    Console.WriteLine($"  🔍 Searching: \"{query}\"");
    using var http = new HttpClient();
    var encoded = WebUtility.UrlEncode(query);
    // Use DuckDuckGo Instant Answer API (no key required)
    var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
    var json = http.GetStringAsync(url).GetAwaiter().GetResult();
    using var doc = JsonDocument.Parse(json);
    var root = doc.RootElement;

    var results = new List<string>();

    // Collect the abstract
    var abs = root.GetProperty("Abstract").GetString();
    if (!string.IsNullOrWhiteSpace(abs))
        results.Add($"[Summary] {abs}");

    // Collect related topics
    if (root.TryGetProperty("RelatedTopics", out var topics))
    {
        foreach (var topic in topics.EnumerateArray().Take(8))
        {
            var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
            if (!string.IsNullOrWhiteSpace(text))
                results.Add(text);
        }
    }

    if (results.Count == 0)
        return $"No results found for \"{query}\". Try a different or broader query.";

    return string.Join("\n\n", results);
}

[Description("Save a research note. Use this to record key findings, facts, or insights as you research.")]
string SaveNote([Description("The note content to save")] string note)
{
    notes.Add(note);
    Console.WriteLine($"  📝 Note saved ({notes.Count} total)");
    return $"Note saved. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved research notes so far.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";
    return string.Join("\n---\n", notes.Select((n, i) => $"[{i + 1}] {n}"));
}

// --- Agent setup ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearch),
        AIFunctionFactory.Create(SaveNote),
        AIFunctionFactory.Create(GetNotes),
    ]
};

var systemPrompt = """
    You are a research agent. Given a topic, you autonomously research it by:
    1. Breaking the topic into useful search queries.
    2. Using the WebSearch tool to find information (search multiple times with different queries).
    3. Using SaveNote to record key findings as you go.
    4. After gathering enough information, using GetNotes to review everything.
    5. Finally, producing a well-structured summary with key facts, organized by theme.

    Be thorough — make at least 3 different searches before summarizing.
    Always save notes before producing the final summary.
    """;

// --- Interactive loop ---

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬 AI Research Agent           ║");
Console.WriteLine("╠══════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or       ║");
Console.WriteLine("║  type 'quit' to exit.                ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Research topic> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notes.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary:\n\n{topic}")
    };

    Console.WriteLine($"\n🚀 Researching: {topic}\n");

    var response = await client.GetResponseAsync(messages, chatOptions);
    Console.WriteLine("\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    Console.WriteLine(response.Text);
    Console.WriteLine("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n");
}

